        $(document).ready(function () {

            // noscript
            $("#toggle_filters").show();
            if ($("#pnlResults").length != 0) {
                $("#pnlForm").hide();
            }

            // reset fields completely
            $("#btnReset").click(function () {
                $(".p_notice").css('opacity', '1'); // all fields empty
                $(".table_filters input[type='text']").removeAttr('value');
                $(".table_filters select option:selected").removeAttr('selected');
            });

            $(".table_filters input[type='text'], .table_filters select").change(function () {
                if (toggleNotice()) {
                    $(".p_notice").css('opacity', '1'); // all fields empty
                }
                else {
                    $(".p_notice").css('opacity', '0.3');
                }
            });

            $("#toggle_filters").click(function () {
                if ($(this).hasClass("toggle_open")) {
                    $(this).removeClass("toggle_open").addClass("toggle_close");
                    $(this).html("&uarr; Hide Search Parameters");
                    $("#pnlForm").slideToggle('slow');
                }
                else if ($(this).hasClass("toggle_close")) {
                    $(this).removeClass("toggle_close").addClass("toggle_open");
                    $(this).html("&darr; Show Search Parameters");
                    $("#pnlForm").slideToggle('slow');
                }
                else { }
            });

            $('.toggleRPpos').click(function () {
                if ($('div.rangePicker').css('float') == 'left') {
                    $('div.rangePicker').css('float', 'right');
                    $('.toggleRPpos').html('Align date picker to the left');
                }
                else {
                    $('div.rangePicker').css('float', 'left');
                    $('.toggleRPpos').html('Align date picker to the right');
                }
                return false;
            });

            // create date picker by replacing out the inputs
            $('.rangePicker').html('<a href="#" class="range_prev"><span>Previous</span></a><a href="#" class="rangeDisplay"><span>Pick a Date</span></a><a href="#" class="range_next"><span>Next</span></a>').dateRangePicker({ menuSet: 'pastRange' });
        });

        function toggleNotice(obj) {
            var allEmpty = true;

            $(".required_group").each(function () {
                // length of value
                if ($(this).val().length > 0) {
                    allEmpty = false;
                    return false; // exit out of loop
                }
            });
            return allEmpty;
        }
